type TradeDealsArgs struct {
	Home  string `json:"home"`
	Owner string `json:"owner"`
	Bench string `json:"bench"`
}

// Deals yields the items of trade_deals, forever.
//
// Each deal the workbench's venue makes, oldest first, as its History tab lists it: ticket, order, position, market, side, entry, time, price, volume, commission, swap, profit and magic, and its reason (order: an order made it; sl, tp or stop_out: the venue's own stop, target or stop-out closed the position; venue: the venue made it by itself); at most 1000 a page. next is the count of deals read.
// Scope: read. Since: 1.0.0.
// URI: bentrix://{home}/{owner}/bench/{bench}/deals{?after}
// opts.After: the cursor to read since; empty yields only what is new.
